<?php
if(session_status()!==PHP_SESSION_ACTIVE) session_start(); require_once __DIR__.'/../../connection/database.php'; require_once __DIR__.'/../../includes/conciliacion_periodos.php';
header('Cache-Control: no-store');
if(empty($_SESSION['user_id'])) { header('Location: ../../index.html?sesion=requerida'); exit; }
$pdo=database(); $usuario=(int)$_SESSION['user_id'];
if(!conciliacionPropietario($pdo,$usuario)) { http_response_code(403); exit('Este mantenimiento es exclusivo del propietario Superusuario.'); }
function cp($v): string { return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$_SESSION['periodos_csrf']=$_SESSION['periodos_csrf']??bin2hex(random_bytes(32)); $error=''; $mensaje=$_SESSION['periodos_mensaje']??''; unset($_SESSION['periodos_mensaje']);
if($_SERVER['REQUEST_METHOD']==='POST') try {
    if(!is_string($_POST['csrf']??null) || !hash_equals($_SESSION['periodos_csrf'],$_POST['csrf'])) throw new RuntimeException('El formulario venció.');
    conciliacionAdministrar($pdo,$usuario,$_POST); $_SESSION['periodos_mensaje']='Cambio registrado en bitácora.'; header('Location: control_periodos.php'); exit;
} catch(Throwable $e) { error_log($e->getMessage()); $error=$e instanceof PDOException?'No se pudo guardar el cambio.':$e->getMessage(); }
$periodo=conciliacionPeriodo($pdo); $periodos=$pdo->query('SELECT * FROM conciliacion_periodos ORDER BY mes DESC')->fetchAll();
$usuarios=$pdo->query('SELECT id,usuario,nombre_completo FROM usuarios WHERE estado=1 AND id_rol IN (2,4,5) ORDER BY nombre_completo')->fetchAll();
$estados=$pdo->query('SELECT e.*,b.descripcion banco FROM estados_cuenta e LEFT JOIN bancos b ON b.id=e.id_banco WHERE NOT EXISTS(SELECT 1 FROM conciliacion_cierres c WHERE c.estado_cuenta_id=e.id) ORDER BY e.id DESC')->fetchAll();
$autorizaciones=$pdo->query("SELECT a.*,u.nombre_completo,p.mes,(NOT a.revocado AND a.vence_en>CURRENT_TIMESTAMP AND p.estado='ABIERTO' AND NOT EXISTS(SELECT 1 FROM conciliacion_cierres cc WHERE cc.estado_cuenta_id=a.estado_cuenta_id)) vigente FROM conciliacion_autorizaciones a JOIN usuarios u ON u.id=a.usuario_id JOIN conciliacion_periodos p ON p.id=a.periodo_id ORDER BY a.id DESC LIMIT 100")->fetchAll();
$historial=$pdo->query('SELECT b.*,u.nombre_completo FROM conciliacion_control_bitacora b JOIN usuarios u ON u.id=b.usuario_id ORDER BY b.id DESC LIMIT 100')->fetchAll();
function csrfPeriodo(): void { echo '<input type="hidden" name="csrf" value="'.cp($_SESSION['periodos_csrf']).'">'; }
?><!DOCTYPE html><html lang="es"><head><?php include __DIR__.'/../../includes/head.php'; ?><link rel="stylesheet" href="../../assets/css/pages/conciliacion.css?v=<?=filemtime(__DIR__.'/../../assets/css/pages/conciliacion.css')?>"></head><body><div id="app"><div id="sidebar" class="active"><?php include __DIR__.'/../../includes/menu_sidebar.php'; ?></div><main id="main" class="cruce-app"><h3>Control de períodos</h3><p>Mantenimiento exclusivo de tu usuario. Mes abierto: <strong><?=cp($periodo['MES']??'Ninguno')?></strong>.</p>
<?php if($error): ?><div class="alert alert-warning"><?=cp($error)?></div><?php endif; if($mensaje): ?><div class="alert alert-success"><?=cp($mensaje)?></div><?php endif; ?>
<section class="card"><div class="card-body"><h5>Habilitar mes de trabajo</h5><p>Solo un mes puede estar abierto. Habilitar otro bloquea el anterior y revoca las autorizaciones excepcionales; no cierra ni reabre estados bancarios.</p><form method="post"><?php csrfPeriodo(); ?><input type="hidden" name="accion" value="abrir_periodo"><label>Mes<input class="form-control" type="month" name="mes" value="<?=cp(substr($periodo['MES']??date('Y-m-d'),0,7))?>" required></label><label class="d-block mt-2">Motivo<textarea class="form-control" name="motivo" maxlength="1000" required></textarea></label><button class="btn btn-primary mt-2">Habilitar este mes</button></form>
<?php if($periodo): ?><form class="mt-4" method="post"><?php csrfPeriodo(); ?><input type="hidden" name="accion" value="cerrar_periodo"><label>Motivo para cerrar el mes<input class="form-control" name="motivo" maxlength="1000" required></label><button class="btn btn-outline-primary mt-2">Cerrar mes administrativo</button></form><?php endif; ?></div></section>
<section class="card"><div class="card-body"><h5>Autorizar ajustes y cierre excepcional</h5><p>El usuario autorizado verá el formulario únicamente en el estado seleccionado del mes abierto. El permiso no lo convierte en Supervisor ni le permite gestionar períodos.</p><form method="post"><?php csrfPeriodo(); ?><input type="hidden" name="accion" value="autorizar"><label class="d-block">Usuario<select class="form-select" name="usuario" required><option value="">Seleccionar</option><?php foreach($usuarios as $u): ?><option value="<?=(int)$u['ID']?>"><?=cp($u['NOMBRE_COMPLETO'])?> (<?=cp($u['USUARIO'])?>)</option><?php endforeach; ?></select></label><label class="d-block mt-2">Estado de cuenta<select class="form-select" name="estado_cuenta" required><option value="">Seleccionar</option><?php foreach($estados as $e): if(!conciliacionEnPeriodo($periodo,$e)) continue; ?><option value="<?=(int)$e['ID']?>">#<?=(int)$e['ID']?> · <?=cp($e['BANCO'])?> · <?=cp($e['NUMERO_CUENTA'])?> · <?=cp($e['MONEDA'])?></option><?php endforeach; ?></select></label><label class="d-block mt-2">Vence (hora de Honduras)<input class="form-control" type="datetime-local" name="vence" required></label><label class="d-block mt-2">Motivo de autorización<textarea class="form-control" name="motivo" maxlength="1000" required></textarea></label><button class="btn btn-primary mt-2">Otorgar permiso limitado</button></form></div></section>
<section class="card"><div class="card-body cruce-table-wrap"><h5>Autorizaciones</h5><table class="table"><thead><tr><th>Usuario</th><th>Mes / estado</th><th>Vencimiento</th><th>Situación</th><th>Acción</th></tr></thead><tbody><?php foreach($autorizaciones as $a): ?><tr><td><?=cp($a['NOMBRE_COMPLETO'])?></td><td><?=cp($a['MES'])?> / #<?=(int)$a['ESTADO_CUENTA_ID']?></td><td><?=cp($a['VENCE_EN'])?></td><td><?=$a['REVOCADO']?'Revocado':($a['VIGENTE']?'Vigente':'Vencido o estado bloqueado/cerrado')?></td><td><?php if(!$a['REVOCADO']): ?><form method="post"><?php csrfPeriodo(); ?><input type="hidden" name="accion" value="revocar"><input type="hidden" name="autorizacion" value="<?=(int)$a['ID']?>"><label>Motivo<input name="motivo" class="form-control" required maxlength="1000"></label><button class="btn btn-outline-primary btn-sm">Revocar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><h5>Historial de meses</h5><table class="table"><thead><tr><th>Mes</th><th>Estado</th><th>Último cambio</th></tr></thead><tbody><?php foreach($periodos as $p): ?><tr><td><?=cp($p['MES'])?></td><td><?=cp($p['ESTADO'])?></td><td><?=cp($p['ACTUALIZADO_EN'])?></td></tr><?php endforeach; ?></tbody></table><h5>Bitácora de control</h5><table class="table"><thead><tr><th>Fecha / usuario</th><th>Acción</th><th>Motivo</th></tr></thead><tbody><?php foreach($historial as $h): ?><tr><td><?=cp($h['CREADO_EN'])?><br><?=cp($h['NOMBRE_COMPLETO'])?></td><td><?=cp($h['ACCION'])?></td><td><?=cp($h['MOTIVO'])?></td></tr><?php endforeach; ?></tbody></table></div></section>
